// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount, address owner) public {
        vm.assume(owner != address(0));
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustDifficulty(1234);
        uint256 difficultyBefore = c.currentDifficulty();
        vm.prank(owner);
        try c.AdjustBetAmounts(amount) { } catch { }
        assertTrue(c.currentDifficulty() == difficultyBefore);
    }
}
